func resolve_jump_chain(chain: Array, start_player: int) -> int:
    var skips: int = 0
    var i: int = 0
    while i < chain.size():
        var card: CardData = chain[i]
        if card.rank == CardTypes.Ranks.JACK:
            skips += 1
            i += 1
        elif card.rank == CardTypes.Ranks.KING:
            reverse_turn_order()
            i += 1
        else:
            break
    return (start_player + skips + 1) % 4

practicePrompt.solutionCode:
func recursive_skips(chain: Array, i: int) -> int:
    if i >= chain.size():
        return 0
    if chain[i].rank != CardTypes.Ranks.JACK:
        return 0
    return 1 + recursive_skips(chain, i + 1)

